<?php
session_start();
require '../../includes/conexao.php';
require '../../includes/verificar_sessao.php';
verificar_perfil('Secretaria');

$tipo = $_GET['tipo'] ?? $_POST['tipo'] ?? 'professor_disciplina';
$tipos = ['professor_disciplina' => 'Professor e disciplina', 'turma_disciplina' => 'Turma, disciplina e professor', 'horario' => 'Horários'];
if (!isset($tipos[$tipo])) { $tipo = 'professor_disciplina'; }
$mensagem = '';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $id = intval($_POST['id'] ?? 0);
    if (isset($_POST['remover']) && $id > 0) {
        $tabela = $tipo === 'professor_disciplina' ? 'professor_disciplina' : ($tipo === 'turma_disciplina' ? 'turma_disciplina' : 'horario');
        $chave = $tipo === 'professor_disciplina' ? 'id_professor_disciplina' : ($tipo === 'turma_disciplina' ? 'id_turma_disciplina' : 'id_horario');
        $stmt = $conexao->prepare("DELETE FROM $tabela WHERE $chave=?");
        $stmt->bind_param('i', $id);
        $ok = $stmt->execute();
        $stmt->close();
        $mensagem = $ok ? '<div class="sucesso">Vínculo removido com sucesso.</div>' : '<div class="erro">Não foi possível remover o vínculo.</div>';
    } elseif ($tipo === 'professor_disciplina') {
        $professor = intval($_POST['id_professor'] ?? 0); $disciplina = intval($_POST['id_disciplina'] ?? 0);
        if ($professor > 0 && $disciplina > 0) {
            $stmt = $conexao->prepare('SELECT COUNT(*) AS total FROM professor_disciplina WHERE id_professor=? AND id_disciplina=?'); $stmt->bind_param('ii', $professor, $disciplina); $stmt->execute(); $existe=(int)$stmt->get_result()->fetch_assoc()['total']>0; $stmt->close();
            if ($existe) { $mensagem='<div class="aviso">Esse vínculo já existe.</div>'; } else { $stmt=$conexao->prepare('INSERT INTO professor_disciplina (id_professor,id_disciplina) VALUES (?,?)');$stmt->bind_param('ii',$professor,$disciplina);$ok=$stmt->execute();$stmt->close();$mensagem=$ok?'<div class="sucesso">Vínculo criado com sucesso.</div>':'<div class="erro">Não foi possível criar o vínculo.</div>'; }
        }
    } elseif ($tipo === 'turma_disciplina') {
        $turma=intval($_POST['id_turma']??0);$disciplina=intval($_POST['id_disciplina']??0);$professor=intval($_POST['id_professor']??0);
        if($turma>0&&$disciplina>0&&$professor>0){$stmt=$conexao->prepare('SELECT COUNT(*) AS total FROM turma_disciplina WHERE id_turma=? AND id_disciplina=? AND id_professor=?');$stmt->bind_param('iii',$turma,$disciplina,$professor);$stmt->execute();$existe=(int)$stmt->get_result()->fetch_assoc()['total']>0;$stmt->close();if($existe){$mensagem='<div class="aviso">Esse vínculo já existe.</div>';}else{$stmt=$conexao->prepare('INSERT INTO turma_disciplina(id_turma,id_disciplina,id_professor) VALUES(?,?,?)');$stmt->bind_param('iii',$turma,$disciplina,$professor);$ok=$stmt->execute();$stmt->close();$mensagem=$ok?'<div class="sucesso">Vínculo criado com sucesso.</div>':'<div class="erro">Não foi possível criar o vínculo.</div>';}}
    } else {
        $vinculo=intval($_POST['id_turma_disciplina']??0);$dia=$_POST['dia_semana']??'';$inicio=$_POST['hora_inicio']??'';$fim=$_POST['hora_fim']??'';
        if($vinculo>0&&in_array($dia,['Segunda','Terça','Quarta','Quinta','Sexta'],true)&&$inicio!==''&&$fim!==''){$stmt=$conexao->prepare('INSERT INTO horario(id_turma_disciplina,dia_semana,hora_inicio,hora_fim) VALUES(?,?,?,?)');$stmt->bind_param('isss',$vinculo,$dia,$inicio,$fim);$ok=$stmt->execute();$stmt->close();$mensagem=$ok?'<div class="sucesso">Horário criado com sucesso.</div>':'<div class="erro">Não foi possível criar o horário.</div>';}
    }
}

$professores=[];$result=$conexao->query("SELECT id_usuario,nome FROM usuario WHERE perfil='Professor' AND ativo=1 ORDER BY nome");while($row=$result->fetch_assoc()){$professores[]=$row;}
$disciplinas=[];$result=$conexao->query('SELECT id_disciplina,nome FROM disciplina ORDER BY nome');while($row=$result->fetch_assoc()){$disciplinas[]=$row;}
$turmas=[];$result=$conexao->query('SELECT id_turma,nome,ano_letivo,periodo FROM turma ORDER BY nome');while($row=$result->fetch_assoc()){$turmas[]=$row;}
$vinculos=[];$result=$conexao->query('SELECT td.id_turma_disciplina,t.nome AS turma_nome,d.nome AS disciplina_nome,u.nome AS professor_nome FROM turma_disciplina td JOIN turma t ON t.id_turma=td.id_turma JOIN disciplina d ON d.id_disciplina=td.id_disciplina JOIN usuario u ON u.id_usuario=td.id_professor ORDER BY t.nome,d.nome');while($row=$result->fetch_assoc()){$vinculos[]=$row;}
$professor_vinculos=[];$result=$conexao->query('SELECT pd.id_professor_disciplina,u.nome AS professor_nome,d.nome AS disciplina_nome FROM professor_disciplina pd JOIN usuario u ON u.id_usuario=pd.id_professor JOIN disciplina d ON d.id_disciplina=pd.id_disciplina ORDER BY u.nome,d.nome');while($row=$result->fetch_assoc()){$professor_vinculos[]=$row;}
$horarios=[];$result=$conexao->query("SELECT h.id_horario,h.dia_semana,h.hora_inicio,h.hora_fim,t.nome AS turma_nome,d.nome AS disciplina_nome,u.nome AS professor_nome FROM horario h JOIN turma_disciplina td ON td.id_turma_disciplina=h.id_turma_disciplina JOIN turma t ON t.id_turma=td.id_turma JOIN disciplina d ON d.id_disciplina=td.id_disciplina JOIN usuario u ON u.id_usuario=td.id_professor ORDER BY t.nome,h.dia_semana,h.hora_inicio");while($row=$result->fetch_assoc()){$horarios[]=$row;}
?>
<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Secretaria | Relações</title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f3f6fb;color:#1f2937}main{max-width:1120px;margin:32px auto;padding:0 20px 40px}.header{background:linear-gradient(135deg,#0d3d70,#1b8ac0);color:#fff;border-radius:18px;padding:26px 28px;margin-bottom:24px}.header h1{margin:0;font-size:2rem}.tabs{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}.tabs a{padding:10px 14px;border-radius:9px;background:#eaf3ff;color:#0b447d;text-decoration:none;font-weight:bold}.tabs .ativo{background:#0d4a8f;color:#fff}.panel{background:#fff;border:1px solid #e2eaf5;border-radius:18px;padding:22px;margin-bottom:20px;box-shadow:0 8px 20px rgba(15,23,42,.04)}.panel h2{margin-top:0;color:#123d70}.form{display:flex;gap:12px;flex-wrap:wrap;align-items:end}.campo{display:flex;flex-direction:column;gap:6px;min-width:190px}.campo label{font-size:.78rem;font-weight:bold;color:#45556b}.campo select,.campo input{padding:9px;border:1px solid #dfe8f4;border-radius:8px;background:#f9fbff}.btn{border:0;border-radius:8px;padding:10px 15px;background:#0d4a8f;color:#fff;font-weight:bold;cursor:pointer}.tabela{width:100%;border-collapse:collapse}.tabela th,.tabela td{padding:11px;border-bottom:1px solid #edf2f9;text-align:left;font-size:.85rem}.tabela th{font-size:.72rem;color:#6b7280;text-transform:uppercase}.remover{background:#fbe9ea;color:#b3262f;border:0;border-radius:7px;padding:7px 10px;cursor:pointer}.sucesso,.erro,.aviso{padding:10px 12px;border-radius:8px;margin-bottom:15px}.sucesso{background:#eaf7ee;color:#1d6f3b}.erro{background:#fee;color:#9d1c1c}.aviso{background:#fff4e5;color:#8a5a00}</style></head><body><?php include '../../includes/menu_secretaria.php';?><main><section class="header"><h1>Relações administrativas</h1></section><nav class="tabs"><?php foreach($tipos as $chave=>$nome):?><a class="<?php echo $tipo===$chave?'ativo':'';?>" href="?tipo=<?php echo $chave;?>"><?php echo $nome;?></a><?php endforeach;?></nav><?php echo $mensagem;?><section class="panel"><?php if($tipo==='professor_disciplina'):?><h2>Vincular professor e disciplina</h2><form class="form" method="POST"><input type="hidden" name="tipo" value="professor_disciplina"><div class="campo"><label>Professor</label><select name="id_professor" required><option value="">Selecione</option><?php foreach($professores as $item):?><option value="<?php echo $item['id_usuario'];?>"><?php echo htmlspecialchars($item['nome']);?></option><?php endforeach;?></select></div><div class="campo"><label>Disciplina</label><select name="id_disciplina" required><option value="">Selecione</option><?php foreach($disciplinas as $item):?><option value="<?php echo $item['id_disciplina'];?>"><?php echo htmlspecialchars($item['nome']);?></option><?php endforeach;?></select></div><button class="btn">Adicionar</button></form><h2 style="margin-top:26px">Vínculos existentes</h2><table class="tabela"><tr><th>Professor</th><th>Disciplina</th><th>Ação</th></tr><?php foreach($professor_vinculos as $item):?><tr><td><?php echo htmlspecialchars($item['professor_nome']);?></td><td><?php echo htmlspecialchars($item['disciplina_nome']);?></td><td><form method="POST"><input type="hidden" name="tipo" value="professor_disciplina"><input type="hidden" name="id" value="<?php echo $item['id_professor_disciplina'];?>"><button class="remover" name="remover">Remover</button></form></td></tr><?php endforeach;?></table>
<?php elseif($tipo==='turma_disciplina'):?><h2>Vincular turma, disciplina e professor</h2><form class="form" method="POST"><input type="hidden" name="tipo" value="turma_disciplina"><div class="campo"><label>Turma</label><select name="id_turma" required><option value="">Selecione</option><?php foreach($turmas as $item):?><option value="<?php echo $item['id_turma'];?>"><?php echo htmlspecialchars($item['nome'].' - '.$item['ano_letivo']);?></option><?php endforeach;?></select></div><div class="campo"><label>Disciplina</label><select name="id_disciplina" required><option value="">Selecione</option><?php foreach($disciplinas as $item):?><option value="<?php echo $item['id_disciplina'];?>"><?php echo htmlspecialchars($item['nome']);?></option><?php endforeach;?></select></div><div class="campo"><label>Professor</label><select name="id_professor" required><option value="">Selecione</option><?php foreach($professores as $item):?><option value="<?php echo $item['id_usuario'];?>"><?php echo htmlspecialchars($item['nome']);?></option><?php endforeach;?></select></div><button class="btn">Adicionar</button></form><h2 style="margin-top:26px">Vínculos existentes</h2><table class="tabela"><tr><th>Turma</th><th>Disciplina</th><th>Professor</th><th>Ação</th></tr><?php foreach($vinculos as $item):?><tr><td><?php echo htmlspecialchars($item['turma_nome']);?></td><td><?php echo htmlspecialchars($item['disciplina_nome']);?></td><td><?php echo htmlspecialchars($item['professor_nome']);?></td><td><form method="POST"><input type="hidden" name="tipo" value="turma_disciplina"><input type="hidden" name="id" value="<?php echo $item['id_turma_disciplina'];?>"><button class="remover" name="remover">Remover</button></form></td></tr><?php endforeach;?></table>
<?php else:?><h2>Cadastrar horário</h2><form class="form" method="POST"><input type="hidden" name="tipo" value="horario"><div class="campo"><label>Turma, disciplina e professor</label><select name="id_turma_disciplina" required><option value="">Selecione</option><?php foreach($vinculos as $item):?><option value="<?php echo $item['id_turma_disciplina'];?>"><?php echo htmlspecialchars($item['turma_nome'].' - '.$item['disciplina_nome'].' - '.$item['professor_nome']);?></option><?php endforeach;?></select></div><div class="campo"><label>Dia</label><select name="dia_semana" required><option>Segunda</option><option>Terça</option><option>Quarta</option><option>Quinta</option><option>Sexta</option></select></div><div class="campo"><label>Início</label><input type="time" name="hora_inicio" required></div><div class="campo"><label>Fim</label><input type="time" name="hora_fim" required></div><button class="btn">Adicionar</button></form><h2 style="margin-top:26px">Horários existentes</h2><table class="tabela"><tr><th>Turma</th><th>Disciplina</th><th>Professor</th><th>Dia</th><th>Horário</th><th>Ação</th></tr><?php foreach($horarios as $item):?><tr><td><?php echo htmlspecialchars($item['turma_nome']);?></td><td><?php echo htmlspecialchars($item['disciplina_nome']);?></td><td><?php echo htmlspecialchars($item['professor_nome']);?></td><td><?php echo htmlspecialchars($item['dia_semana']);?></td><td><?php echo htmlspecialchars(substr($item['hora_inicio'],0,5).' - '.substr($item['hora_fim'],0,5));?></td><td><form method="POST"><input type="hidden" name="tipo" value="horario"><input type="hidden" name="id" value="<?php echo $item['id_horario'];?>"><button class="remover" name="remover">Remover</button></form></td></tr><?php endforeach;?></table><?php endif;?></section></main></body></html>
